import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·25","description":"易小帖 - 卷二·25","frontmatter":{"title":"卷二·25","description":"易小帖 - 卷二·25"},"headers":[],"relativePath":"zh/classics/yixiaotie/065.md","filePath":"zh/classics/yixiaotie/065.md"}'),o={name:"zh/classics/yixiaotie/065.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·25",tabindex:"-1"},[r("卷二·25 "),e("a",{class:"header-anchor",href:"#卷二·25","aria-label":"Permalink to “卷二·25”"},"​")],-1),e("p",null,"十二闢卦十二月卦也，自復至夬而為乾，自姤至剝而為坤，凡十二卦。配十二月，每一卦為一月之主。闢者君也，主也，謂主一月之卦也。若推易之法，則適以此十二卦為聚卦，為他卦移易之主，亦名十二闢卦。其或以乾坤二聚卦無移易法則，又去此二卦名十闢卦。故漢儒又有十闢卦之說。宋朱震，元朱升，倣漢儒說作十闢，卦變是也。其又名六闢卦，如《乾鑿度》洛書摘六闢以建紀，則又去十二之半者。若晁景迂謂歸藏偽書中及十二闢卦，似闢卦之說，在夏商已有之，則以歸藏本後儒偽撰而闢卦之說在偽書前，遂襲取之，非有他耳。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
